const int kNumBins = bins->kNumBins;
    const int kNumBinPlanes = kNumBins - 1;

    // Precompute inverse of bounding box extent
    const real3<T> binSize = {
        (bmax[0] - bmin[0]) / static_cast<T>(kNumBins),
        (bmax[1] - bmin[1]) / static_cast<T>(kNumBins),
        (bmax[2] - bmin[2]) / static_cast<T>(kNumBins)
    };
    const real3<T> invBinSize = {
        static_cast<T>(1) / binSize[0],
        static_cast<T>(1) / binSize[1],
        static_cast<T>(1) / binSize[2]
    };

    // Precompute surface area of bounding box
    const real3<T> extent = bmax - bmin;
    const T totalSurfaceArea = static_cast<T>(2) * (extent[0] * extent[1] + extent[0] * extent[2] + extent[1] * extent[2]);

    T minCost = std::numeric_limits<T>::max();
    int minCostSplitBin = 0;
    int axis = 0;

    // Evaluate SAH for each axis
    for (int a = 0; a < 3; ++a) {
        // Skip axis with zero extent
        if (extent[a] == static_cast<T>(0)) continue;

        // Compute right bounds for each bin plane
        T rightBounds[kNumBinPlanes];
        T rightCount[kNumBinPlanes];
        T rightArea[kNumBinPlanes];

        // Initialize right side
        rightBounds[kNumBinPlanes - 1] = bmax[a];
        rightCount[kNumBinPlanes - 1] = bins->binInfos[a][kNumBins - 1].count;
        rightArea[kNumBinPlanes - 1] = bins->binInfos[a][kNumBins - 1].bounds[1];

        for (int i = kNumBinPlanes - 2; i >= 0; --i) {
            rightBounds[i] = bins->binInfos[a][i + 1].bounds[0];
            rightCount[i] = rightCount[i + 1] + bins->binInfos[a][i].count;
            rightArea[i] = rightArea[i + 1] + bins->binInfos[a][i].bounds[1] - bins->binInfos[a][i].bounds[0];
        }

        // Initialize left side
        T leftBounds = bmin[a];
        T leftCount = 0;
        T leftArea = 0;

        // Evaluate SAH for each bin plane
        for (int i = 0; i < kNumBinPlanes; ++i) {
            leftCount += bins->binInfos[a][i].count;
            leftArea += bins->binInfos[a][i].bounds[1] - bins->binInfos[a][i].bounds[0];

            const T leftSurfaceArea = static_cast<T>(2) * (extent[(a + 1) % 3] * extent[(a + 2) % 3] +
                extent[(a + 1) % 3] * leftArea + extent[(a + 2) % 3] * leftArea);
            const T rightSurfaceArea = static_cast<T>(2) * (extent[(a + 1) % 3] * extent[(a + 2) % 3] +
                extent[(a + 1) % 3] * rightArea[i] + extent[(a + 2) % 3] * rightArea[i]);

            const T cost = static_cast<T>(1) + (leftCount * leftSurfaceArea + rightCount[i] * rightSurfaceArea) / totalSurfaceArea;

            if (cost < minCost) {
                minCost = cost;
                minCostSplitBin = i;
                axis = a;
            }
        }
    }

    // Check if we found a valid split
    if (minCost >= std::numeric_limits<T>::max()) {
        return false;
    }

    // Compute cut position
    const T binStart = bmin[axis];
    const T binEnd = bmax[axis];
    const T binOffset = (binEnd - binStart) / static_cast<T>(kNumBins);
    cut_pos[axis] = binStart + binOffset * (minCostSplitBin + 1);
    *minCostAxis = axis;

    return true;
    // END_CODE

